mkdir -p /tmp/bot-check-r6 && cat > /tmp/bot-check-r6/check.mjs <<'EOF'
import assert from 'node:assert/strict';
import { decide } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/knock-inv-g2-3/bot.mjs';

const mk = (over = {}) => ({ userId: 'u1', category: 'marketing', timezone: 'Europe/Istanbul', quietStart: '22:00', quietEnd: '07:30', ...over });
const at = (iso) => new Date(iso);

// Daily cap: 3 allowed, 4th blocked, per customer-local day
let r;
for (let i = 0; i < 3; i++) { r = decide(mk(), at('2026-10-23T10:00:00Z')); assert.deepEqual(r, { send: true, rule: null }); }
assert.deepEqual(decide(mk(), at('2026-10-23T11:00:00Z')), { send: false, rule: 'daily-cap' });

// Transactional ignores cap and quiet hours
assert.deepEqual(decide(mk({ category: 'transactional' }), at('2026-10-23T11:00:00Z')), { send: true, rule: null });
assert.deepEqual(decide(mk({ category: 'transactional', userId: 'u1' }), at('2026-10-23T20:00:00Z')), { send: true, rule: null });

// Local day, not UTC day: Istanbul 2026-10-23 00:30 local = 2026-10-22T21:30Z
// u2 sends 3 at 2026-10-22T21:30Z (local 10-23 00:30), then 2026-10-22T23:50Z (local 10-23 02:50) is quiet-hours? 02:50 is in 22:00-07:30 -> quiet
const u2 = mk({ userId: 'u2' });
// Quiet at local 23:30 must not consume cap
assert.deepEqual(decide(u2, at('2026-10-23T20:30:00Z')), { send: false, rule: 'quiet-hours' }); // local 23:30
// Local 2026-10-24 07:45 is outside window (07:30 end): 2026-10-24T04:45Z
assert.deepEqual(decide(u2, at('2026-10-24T04:45:00Z')), { send: true, rule: null });
// Cap resets on new local day: local 10-23 13:00 vs 10-24
assert.deepEqual(decide(mk({ userId: 'u3' }), at('2026-10-23T09:00:00Z')).send, true);
assert.deepEqual(decide(mk({ userId: 'u3' }), at('2026-10-23T09:01:00Z')).send, true);
assert.deepEqual(decide(mk({ userId: 'u3' }), at('2026-10-23T09:02:00Z')).send, true);
assert.deepEqual(decide(mk({ userId: 'u3' }), at('2026-10-23T09:03:00Z')), { send: false, rule: 'daily-cap' });
assert.deepEqual(decide(mk({ userId: 'u3' }), at('2026-10-23T21:30:00Z')), { send: true, rule: null }); // local 10-24 00:30 -> wait, that is quiet
EOF
cd /tmp/bot-check-r6 && node check.mjs; echo "exit=$?"

cat > /tmp/bot-check-r6/check.mjs <<'EOF'
import assert from 'node:assert/strict';
import { decide } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/knock-inv-g2-3/bot.mjs';

const mk = (over = {}) => ({ userId: 'u1', category: 'marketing', timezone: 'Europe/Istanbul', quietStart: '22:00', quietEnd: '07:30', ...over });
const at = (iso) => new Date(iso);
const SEND = { send: true, rule: null };
const CAP = { send: false, rule: 'daily-cap' };
const QUIET = { send: false, rule: 'quiet-hours' };

// Istanbul is UTC+3, no DST. Local = UTC + 3h.

// 1. Daily cap: 3 allowed, 4th blocked, same local day
assert.deepEqual(decide(mk(), at('2026-10-23T10:00:00Z')), SEND);   // local 13:00
assert.deepEqual(decide(mk(), at('2026-10-23T10:01:00Z')), SEND);
assert.deepEqual(decide(mk(), at('2026-10-23T10:02:00Z')), SEND);
assert.deepEqual(decide(mk(), at('2026-10-23T11:00:00Z')), CAP);

// 2. Transactional ignores cap and quiet hours, and does not consume marketing cap
assert.deepEqual(decide(mk({ category: 'transactional' }), at('2026-10-23T11:00:00Z')), SEND);
assert.deepEqual(decide(mk({ category: 'transactional' }), at('2026-10-23T20:00:00Z')), SEND); // local 23:00, quiet
const fresh = mk({ userId: 'u-fresh' });
assert.deepEqual(decide({ ...fresh, category: 'transactional' }, at('2026-10-23T10:00:00Z')), SEND);
for (let i = 0; i < 3; i++) assert.deepEqual(decide(fresh, at('2026-10-23T10:00:00Z')), SEND); // cap still empty

// 3. Quiet-hours check runs before cap and does not consume cap
const q = mk({ userId: 'u-quiet' });
assert.deepEqual(decide(q, at('2026-10-23T20:30:00Z')), QUIET); // local 23:30
assert.deepEqual(decide(q, at('2026-10-23T02:00:00Z')), QUIET); // local 05:00
assert.deepEqual(decide(q, at('2026-10-23T04:29:00Z')), QUIET); // local 07:29
assert.deepEqual(decide(q, at('2026-10-23T04:30:00Z')), SEND);  // local 07:30, window end is exclusive
// Quiet calls did not use up the cap
assert.deepEqual(decide(q, at('2026-10-23T04:31:00Z')), SEND);
assert.deepEqual(decide(q, at('2026-10-23T04:32:00Z')), SEND);
assert.deepEqual(decide(q, at('2026-10-23T04:33:00Z')), CAP);

// 4. Local day, not UTC day. Same instant, two zones:
// 2026-10-23T22:30Z is 01:30 on 10-24 in Istanbul but 15:30 on 10-23 in New York.
const ist = mk({ userId: 'u-day', timezone: 'Europe/Istanbul', quietStart: '00:00', quietEnd: '00:00' });
const nyc = mk({ userId: 'u-day-ny', timezone: 'America/New_York', quietStart: '00:00', quietEnd: '00:00' });
for (let i = 0; i < 3; i++) assert.deepEqual(decide(ist, at('2026-10-23T22:30:00Z')), SEND); // local 10-24
assert.deepEqual(decide(ist, at('2026-10-23T22:31:00Z')), CAP);
// Istanbul local 10-24 counter is separate from New York's local 10-23 counter
assert.deepEqual(decide(nyc, at('2026-10-23T22:30:00Z')), SEND);
// Next Istanbul local day, 10-25 00:30 = 10-24T21:30Z, resets
assert.deepEqual(decide(ist, at('2026-10-24T21:30:00Z')), SEND);

// 5. Wrap-around vs non-wrap windows, and start === end means no quiet window
const day = mk({ userId: 'u-day-window', timezone: 'UTC', quietStart: '13:00', quietEnd: '14:00' });
assert.deepEqual(decide(day, at('2026-10-23T13:30:00Z')), QUIET);
assert.deepEqual(decide(day, at('2026-10-23T14:00:00Z')), SEND);
const none = mk({ userId: 'u-none', timezone: 'UTC', quietStart: '09:00', quietEnd: '09:00' });
assert.deepEqual(decide(none, at('2026-10-23T09:30:00Z')), SEND);

// 6. Input validation throws
const bad = (c, n = at('2026-10-23T10:00:00Z')) => assert.throws(() => decide(c, n), TypeError);
bad(mk({ category: 'promo' }));
bad(mk({ quietStart: '24:00' }));
bad(mk({ quietEnd: '7:30' }));
bad(mk({ userId: '' }));
bad(mk(), new Date('nope'));
assert.throws(() => decide(mk({ timezone: 'Mars/Olympus' }), at('2026-10-23T10:00:00Z')), RangeError);

console.log('all checks passed');
EOF
